# Remove repeated identity prompts added by the retained translation only when
# neither a parenthesis nor the corresponding name occurs in the source text.
import unicodedata
plain=lambda t:''.join(k for k in unicodedata.normalize('NFD',t.casefold()) if not unicodedata.combining(k))
glosses={'Bezukhov':'bezukh','Bezúkhov':'bezukh','Pjotr Bezukhov':'bezukh','Bolkonskij':'bolkon','Bolkónskij':'bolkon','Bolkonski':'bolkon','Bolkonskaja':'bolkon','Bolkónskaja':'bolkon','Rostova':'rostov','Rostov':'rostov','Kuragin':'kuragin','Platon Karatajev':'karata','Drubetskoj':'drubetsk','Boris Drubetskoj':'drubetsk','Jelena':'elena','Karagina':'karagin','Pjotr':'peter','Sofja':'sophia','Nikolai':'nicholas','Shinshin':'shinshin','Nikolenka Bolkonskij':'bolkon','Vera Rostova':'rostov','Anatol Kuragin':'kuragin'}
nameforms={}
for forms in ['Pávlovna Pávlovnas Bezúkhov Bezúkhovs Bezúkhova Bezúkhovas Rostóv Rostóvs Rostóva Rostóvas Rostóverne Rostóvernes Andréj Andréjs Andréjevitj Nikoláj Nikolájs Nikolájevna Nikolájevnas Nikolájevitj Bolkónskij Bolkónskijs Bolkónskaja Vasílij Borís Karatájev Sónja Sónjas Mikhaíl Mikhájlovna Mikháilovitj Natásja Natásjas Denísov Denísovs Kutúzov Kutúzovs Dolókhov Dolókhóv Dolókhóvs Pétja Pétjas Schérer'.split()]:
 for word in forms:nameforms[word]=''.join(x for x in unicodedata.normalize('NFD',word) if not unicodedata.combining(x))
nameforms.update({'Marija':'Marja','Marijas':'Marjas','Bolkonski':'Bolkonskij','Bolkonskis':'Bolkonskijs','Dolokovs':'Dolokhovs','Dolokkov':'Dolokhov','Rostoptsjin':'Rostoptjin','Rostoptsjins':'Rostoptjins','Rostobtjin':'Rostoptjin','Rostobtjins':'Rostoptjins','Rostoptjín':'Rostoptjin'})
nm=re.compile(r'\b(?:'+'|'.join(nameforms)+r')\b')
for c in da['chapters']:
 for p,t in enumerate(c['paragraphs'],1):
  ref=source(c['number'],p);v=t
  if '(' not in ref:
   v=re.sub(r' \(([^()]+)\)',lambda m:'' if m[1] in glosses and glosses[m[1]] not in plain(ref) else m[0],v)
  v=nm.sub(lambda m:nameforms[m[0]],v)
